CREATE TABLE IF NOT EXISTS cata_preguntas (
  id INTEGER PRIMARY KEY,
  texto TEXT NOT NULL,
  opciones TEXT NOT NULL,
  correcta INTEGER NOT NULL,
  explicacion TEXT
);

CREATE TABLE IF NOT EXISTS cata_respuestas (
  fecha TEXT NOT NULL,
  dispositivo TEXT NOT NULL,
  idx INTEGER NOT NULL,
  pregunta_id INTEGER NOT NULL,
  opcion INTEGER NOT NULL,
  acierto INTEGER NOT NULL,
  creado TEXT DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (fecha, dispositivo, idx)
);
CREATE INDEX IF NOT EXISTS idx_cata_fecha ON cata_respuestas (fecha);

INSERT OR REPLACE INTO cata_preguntas (id, texto, opciones, correcta, explicacion) VALUES
  (1, '¿A qué temperatura se suele servir un tinto crianza?', '["Entre 22 y 24 ºC", "Entre 10 y 12 ºC", "Entre 6 y 8 ºC", "Entre 15 y 18 ºC"]', 3, 'Los tintos con crianza se sirven entre 15 y 18 ºC. Más calientes, el alcohol se nota demasiado.'),
  (2, '¿Qué significa «Crianza» en un tinto de Rioja?', '["Que viene de viñas muy viejas", "Que es un vino joven sin madera", "Que es un vino dulce", "Que ha envejecido al menos 2 años, uno de ellos en barrica"]', 3, 'Un tinto Crianza de Rioja pasa al menos 2 años envejeciendo, con un mínimo de 1 año en barrica.'),
  (3, '¿Cuál es la uva estrella de Ribera del Duero?', '["Tempranillo (Tinta del País)", "Garnacha", "Mencía", "Monastrell"]', 0, 'En Ribera del Duero el Tempranillo se llama Tinta del País o Tinto Fino.'),
  (4, '¿De qué zona son los Albariños más famosos?', '["Jumilla", "Priorat", "Rueda", "Rías Baixas"]', 3, 'Rías Baixas, en Galicia, es la tierra del Albariño.'),
  (5, '¿Con qué uva se hacen la mayoría de blancos de Rueda?', '["Godello", "Verdejo", "Airén", "Macabeo"]', 1, 'El Verdejo es la uva reina de Rueda: fresca, herbácea y con un toque amargo al final.'),
  (6, '¿Cómo se consiguen las burbujas del cava?', '["Con una fermentación en grandes depósitos", "Removiendo mucho el vino", "Con una segunda fermentación dentro de la botella", "Añadiendo gas carbónico"]', 2, 'El cava usa el método tradicional: la segunda fermentación ocurre en la propia botella.'),
  (7, '¿Qué es un Fino?', '["Un tinto ligero de Rioja", "Un rosado de Navarra", "Un cava dulce", "Un vino generoso seco de Jerez criado bajo velo de flor"]', 3, 'El Fino es un vino seco de uva Palomino que se cría bajo una capa de levaduras llamada «flor».'),
  (8, '¿Qué diferencia a la Manzanilla del Fino?', '["No tiene alcohol", "Se cría en Sanlúcar de Barrameda", "Es un vino tinto", "Lleva azúcar añadido"]', 1, 'La Manzanilla es un fino criado en Sanlúcar, junto al mar, lo que le da su toque salino.'),
  (9, '¿En qué zona es más famosa la uva Mencía?', '["Rueda", "Penedés", "Bierzo", "La Mancha"]', 2, 'La Mencía da tintos frescos y frutales en el Bierzo y en la Ribeira Sacra.'),
  (10, '¿Qué uva tinta es típica de Jumilla y Yecla?', '["Tempranillo", "Garnacha blanca", "Albariño", "Monastrell"]', 3, 'La Monastrell aguanta bien el calor del sureste y da tintos carnosos y maduros.'),
  (11, '¿Qué indica «Brut Nature» en un cava?', '["Que es ecológico", "Que no lleva azúcar añadido", "Que es dulce", "Que es rosado"]', 1, 'Brut Nature es el estilo más seco: sin azúcar añadido al final de la elaboración.'),
  (12, '¿Cuál de estos cavas es el más dulce?', '["Semiseco", "Extra Brut", "Brut", "Brut Nature"]', 0, 'De más seco a más dulce: Brut Nature, Extra Brut, Brut, Extra Seco, Seco, Semiseco y Dulce.'),
  (13, '¿Qué significan las siglas D.O.Ca.?', '["Denominación Oficial de Calidad", "De Origen Catalán", "Denominación de Origen Calificada", "Denominación de Origen Cava"]', 2, 'Es la categoría más alta de las denominaciones de origen españolas.'),
  (14, '¿Qué dos zonas españolas tienen Denominación de Origen Calificada?', '["Ribera del Duero y Rueda", "Penedés y Cava", "Rioja y Priorat", "Jerez y Montilla"]', 2, 'Solo Rioja (D.O.Ca.) y Priorat (D.O.Q., en catalán) tienen esta categoría.'),
  (15, '¿Cuánto envejece como mínimo un tinto Reserva de Rioja?', '["3 años, al menos 1 en barrica", "6 meses", "5 años", "1 año"]', 0, 'Un Reserva de Rioja envejece al menos 3 años, con un mínimo de 1 en barrica.'),
  (16, '¿Qué vino va mejor con unas gambas a la plancha?', '["Un blanco fresco", "Un tinto reserva potente", "Un Pedro Ximénez", "Un oporto"]', 0, 'El marisco pide frescura y acidez: un Albariño, un Verdejo o una manzanilla.'),
  (17, '¿Qué es el Pedro Ximénez?', '["Una uva con la que se hacen vinos dulces muy oscuros", "Un tipo de copa", "Un enólogo famoso", "Una bodega de Rioja"]', 0, 'Con la uva Pedro Ximénez, pasificada al sol, se hacen vinos dulces muy intensos.'),
  (18, '¿Qué son los taninos?', '["El aroma a fruta", "Compuestos que dejan sensación de sequedad en la boca", "El azúcar del vino", "Las burbujas"]', 1, 'Los taninos dan esa sensación áspera o secante, sobre todo en los tintos jóvenes y potentes.'),
  (19, '¿De dónde vienen sobre todo los taninos de un tinto?', '["Del corcho", "De la piel y las pepitas de la uva, y de la madera", "Del azúcar", "Del agua"]', 1, 'Los taninos salen de los hollejos, las pepitas y, si hay crianza, de la barrica.'),
  (20, '¿Se puede hacer vino blanco con uva tinta?', '["Solo en Francia", "No, nunca", "Solo añadiendo colorantes", "Sí, si el mosto no está en contacto con la piel"]', 3, 'El color está en la piel. Si se prensa y se separa enseguida, el mosto sale casi blanco.'),
  (21, '¿Qué es un tinto «Roble»?', '["Un tinto con un paso corto por barrica", "Un blanco dulce", "Un vino de más de 10 años", "Un vino sin sulfitos"]', 0, 'Los «Roble» pasan unos meses en barrica: menos que un Crianza, pero ganan algo de tostado.'),
  (22, '¿Qué uva domina en el Priorat junto a la Cariñena?', '["Albariño", "Garnacha", "Palomino", "Verdejo"]', 1, 'Garnacha y Cariñena sobre suelos de pizarra (llicorella) dan los potentes tintos del Priorat.'),
  (23, '¿Con qué uva se hace el Fino de Jerez?', '["Moscatel", "Pedro Ximénez", "Tempranillo", "Palomino"]', 3, 'La Palomino es la uva base de finos, manzanillas, amontillados y olorosos.'),
  (24, 'En Jerez, ¿qué es la «flor»?', '["Un tipo de copa", "Una capa de levaduras que cubre el vino en la bota", "El nombre de la etiqueta", "Una flor que se añade al vino"]', 1, 'La flor protege el vino del aire y le da sus aromas punzantes tan característicos.'),
  (25, '¿Para qué se decanta un vino?', '["Para quitarle alcohol", "Para airearlo o separar los posos", "Para enfriarlo rápido", "Para que tenga burbujas"]', 1, 'Decantar ayuda a abrir aromas en tintos jóvenes y a separar los posos en vinos viejos.'),
  (26, '¿Por dónde se coge la copa de vino?', '["Da igual siempre", "Por la parte ancha", "Por el borde", "Por el tallo"]', 3, 'Cogiéndola por el tallo no calientas el vino con la mano ni manchas la copa.'),
  (27, '¿Qué es la «añada» de un vino?', '["El año de la vendimia", "El año del embotellado", "La graduación", "La edad de la bodega"]', 0, 'La añada es el año en que se recogió la uva. Cada año el clima cambia el vino.'),
  (28, '¿Cuánta uva hace falta, más o menos, para una botella de vino?', '["Unos 100 gramos", "Algo más de 1 kilo", "Unos 5 kilos", "Unos 10 kilos"]', 1, 'Para una botella de 75 cl hace falta, aproximadamente, algo más de 1 kilo de uva.'),
  (29, '¿Qué tres uvas blancas se usan tradicionalmente para el cava?', '["Verdejo, Viura y Godello", "Tempranillo, Garnacha y Graciano", "Albariño, Treixadura y Loureiro", "Macabeo, Xarel·lo y Parellada"]', 3, 'Macabeo, Xarel·lo y Parellada son el trío clásico del cava.'),
  (30, '¿Dónde se elabora la mayor parte del cava?', '["En Jerez", "En el Penedés, sobre todo en Sant Sadurní d''Anoia", "En Rías Baixas", "En Toro"]', 1, 'Sant Sadurní d''Anoia, en Barcelona, es la capital del cava.'),
  (31, '¿Qué rosado es típico de Navarra?', '["El rosado de Verdejo", "El rosado de Albariño", "El rosado de Palomino", "El rosado de Garnacha"]', 3, 'Navarra es famosa por sus rosados de Garnacha, frescos y muy frutales.'),
  (32, '¿A qué temperatura se sirve un cava?', '["Entre 6 y 8 ºC", "Entre 18 y 20 ºC", "Entre 14 y 16 ºC", "A temperatura ambiente"]', 0, 'Bien frío, entre 6 y 8 ºC, para que la burbuja sea fina y refrescante.'),
  (33, 'Si un vino huele a corcho mojado o a moho, ¿qué le pasa?', '["Es un vino muy joven", "Es un vino de gran calidad", "Está «acorchado»: es un defecto", "Es un vino ecológico"]', 2, 'Es un defecto causado sobre todo por un compuesto llamado TCA. Puedes pedir que te lo cambien.'),
  (34, '¿Qué son las «lágrimas» que caen por la copa?', '["Una garantía de calidad", "Sulfitos", "Gotas que tienen que ver con el alcohol y el azúcar", "Restos de jabón"]', 2, 'Cuanto más alcohol o azúcar, más «lágrimas». No indican si el vino es mejor o peor.'),
  (35, '¿Qué uva blanca es típica de Valdeorras?', '["Verdejo", "Airén", "Godello", "Moscatel"]', 2, 'El Godello gallego da blancos con cuerpo, untuosos y elegantes.'),
  (36, '¿De qué zona es la uva Tinta de Toro?', '["Rueda", "Cariñena", "Toro", "Bierzo"]', 2, 'La Tinta de Toro es una variante local del Tempranillo que da tintos muy potentes.'),
  (37, '¿Qué es el Txakoli?', '["Un blanco fresco y ácido del País Vasco", "Un tinto de Rioja", "Un licor de hierbas", "Un cava"]', 0, 'El Txakoli es ligero, fresco y con un punto de aguja. Se sirve escanciado desde lo alto.'),
  (38, '¿En qué vinos se usa el sistema de criaderas y solera?', '["En los rosados jóvenes", "En el cava", "En los blancos de Rueda", "En los generosos, como los de Jerez"]', 3, 'Se mezclan vinos de distintas edades poco a poco, así que el vino final es muy constante.'),
  (39, '¿Qué es un Oloroso?', '["Un generoso de Jerez seco y con crianza en contacto con el aire", "Un vino espumoso", "Un blanco muy joven", "Un tinto de Rioja"]', 0, 'El Oloroso envejece sin velo de flor: es más oscuro, con aromas a nuez y madera, y seco.'),
  (40, '¿Qué vino suele ir bien con un queso azul como el Cabrales?', '["Un vino dulce", "Un rosado ligero", "Un cava Brut Nature", "Un blanco muy joven y ácido"]', 0, 'El contraste salado y dulce funciona de maravilla: prueba un Pedro Ximénez o un moscatel.'),
  (41, '¿Qué es la vendimia?', '["La recogida de la uva", "El embotellado", "La poda de la viña", "La fermentación"]', 0, 'En España suele hacerse entre finales de agosto y octubre.'),
  (42, '¿Qué convierte el azúcar del mosto en alcohol?', '["El corcho", "La barrica de roble", "Las levaduras", "El sol"]', 2, 'Las levaduras se comen el azúcar y producen alcohol y gas carbónico.'),
  (43, '¿Qué es la fermentación maloláctica?', '["Congelar el vino", "Una segunda fermentación que da burbujas", "Transformar el ácido málico en láctico, lo que suaviza el vino", "Añadir leche al vino"]', 2, 'Casi todos los tintos la hacen: el vino pierde acidez «verde» y gana suavidad.'),
  (44, '¿Cuánto vino cabe en una botella normal?', '["50 cl", "70 cl", "75 cl", "1 litro"]', 2, 'La botella estándar es de 75 cl, unas 6 copas.'),
  (45, '¿Cuánto vino cabe en una botella Magnum?', '["1,5 litros", "0,5 litros", "6 litros", "3 litros"]', 0, 'Una Magnum equivale a dos botellas normales. Los vinos suelen envejecer mejor en ella.'),
  (46, '¿Qué uva blanca es la más típica de Rioja?', '["Palomino", "Albariño", "Verdejo", "Viura (Macabeo)"]', 3, 'La Viura es la uva blanca más plantada de Rioja.'),
  (47, '¿Qué es un «Vino de Pago»?', '["Un vino de una sola finca con denominación propia", "Un vino que se paga a plazos", "Un vino del supermercado", "Un vino de oferta"]', 0, 'Es una categoría para fincas concretas con un clima y un suelo propios y reconocidos.'),
  (48, '¿Cuánto envejece como mínimo un tinto Gran Reserva de Rioja?', '["No hay mínimo", "5 años, al menos 2 en barrica", "10 años en barrica", "1 año"]', 1, 'Un Gran Reserva de Rioja necesita al menos 60 meses de envejecimiento, con 24 en barrica.'),
  (49, 'Con una paella de marisco, ¿qué suele ir mejor?', '["Un blanco o un rosado fresco", "Un Pedro Ximénez", "Un oporto", "Un tinto gran reserva muy tánico"]', 0, 'La frescura de un blanco o un rosado acompaña al marisco sin taparlo.'),
  (50, '¿Qué tinto va de maravilla con un cordero asado?', '["Un tinto con cuerpo, como un Ribera crianza", "Una manzanilla", "Un moscatel dulce", "Un cava semiseco"]', 0, 'La grasa del cordero pide un tinto con estructura y taninos.'),
  (51, '¿Por qué se guardan tumbadas las botellas con corcho?', '["Para que no se despegue la etiqueta", "Para que el vino coja aroma", "Para ahorrar espacio", "Para que el corcho no se seque"]', 3, 'Si el corcho está en contacto con el vino no se reseca y no entra aire.'),
  (52, '¿Cuánto aguanta un tinto abierto, bien tapado y en la nevera?', '["Una hora", "Un mes", "Un año", "Unos 2 a 4 días"]', 3, 'Bien tapado y en frío aguanta varios días. Sácalo un rato antes de beberlo.'),
  (53, '¿Qué uva tinta es típica de Canarias?', '["Mencía", "Listán Negro", "Bobal", "Tempranillo"]', 1, 'El Listán Negro da tintos frescos, a veces con un punto volcánico.'),
  (54, '¿Qué uva tinta es la típica de Utiel-Requena?', '["Verdejo", "Palomino", "Albariño", "Bobal"]', 3, 'La Bobal da tintos y rosados con mucho color y fruta.'),
  (55, '¿En qué orden se sirven normalmente los vinos en una comida?', '["Primero el dulce", "Primero el tinto más fuerte", "Da igual el orden", "Del más ligero al más potente: espumoso, blanco, tinto y dulce"]', 3, 'Así cada vino no tapa al siguiente.'),
  (56, '¿Qué aromas da una barrica de roble a un vino?', '["Manzana verde", "Hierba recién cortada", "Limón y pomelo", "Vainilla, tostados y especias"]', 3, 'La madera, sobre todo si está tostada, deja notas de vainilla, coco, café o especias.'),
  (57, '¿Qué hace un sumiller?', '["Fabrica las barricas", "Recoge la uva", "Es el dueño de la viña", "Aconseja y sirve el vino"]', 3, 'El sumiller elige los vinos de un restaurante y te ayuda a acertar con tu plato.'),
  (58, '¿Qué vino acompaña bien un postre de chocolate negro?', '["Un Pedro Ximénez u otro vino dulce", "Un fino", "Un cava Brut Nature", "Un blanco muy ácido y seco"]', 0, 'El chocolate necesita un vino al menos igual de dulce, si no el vino parece amargo.'),
  (59, '¿Qué es el mosto?', '["El zumo de uva antes de fermentar", "El vino ya embotellado", "Un vino dulce de postre", "Los restos de la barrica"]', 0, 'Cuando el mosto fermenta se convierte en vino.'),
  (60, '¿De dónde viene el nombre «Tempranillo»?', '["De que se bebe temprano por la mañana", "De un pueblo llamado Tempranillo", "De que madura pronto", "De que es un vino joven"]', 2, 'Madura antes que otras uvas tintas: es «temprana».');
